"""Hand-authored L23 drafts after actual rendering inspection; independent review pending."""
from authoring_helpers import DraftBatch,formula
b=DraftBatch('W05-L23',5,'L23','Nonlinear and time-varying joint control',695,'robotics-integration-author-L23')
def add(*args,**kwargs):
 kwargs.setdefault('difficulty','easy');return b.add(*args,**kwargs)
matched=['The fully actuated model is known exactly, its mass/inertia matrix is nonsingular, measurements are exact, and the demanded input is available without saturation.']
servo=formula('e=x_d−x; f′=ẍ_d+k_v ė+k_p e; ë+k_v ė+k_p e=0',{'x,x_d':'actual and desired position','e':'desired-minus-actual position error','f′':'normalized commanded acceleration','k_v,k_p':'velocity and position gains','dot and double dot':'first and second time derivatives'},{'x,x_d,e':'m','f′':'m/s²','k_v':'s⁻¹','k_p':'s⁻²'},matched)
angular=formula('e=θ_d−θ; τ=I(θ̈_d+k_v ė+k_p e)+vθ̇+c sgn(θ̇)+mgl cosθ',{'θ,θ_d':'actual and desired angle measured counterclockwise from horizontal right','e':'desired-minus-actual angle error','τ':'actuator torque','I=ml²':'point-mass joint inertia','v':'viscous friction coefficient','c':'Coulomb friction magnitude','m':'point mass','l':'link length','g':'gravitational acceleration','k_v,k_p':'normalized servo gains','sgn':'sign function with sgn(0)=0','dot and double dot':'time derivatives'},{'θ,θ_d,e':'rad','τ,c':'N·m','I':'kg·m²','v':'N·m·s/rad','m':'kg','l':'m','g':'m/s²','k_v':'s⁻¹','k_p':'s⁻²'},['Massless rigid link with point mass at its end.']+matched)
add(697,'configuration-inertia','Distinguish effective inertia from body mass','A rigid arm changes configuration without picking up a load; what can change in its joint-space dynamics?', ['The generalized inertia matrix can change although the individual link masses remain fixed','The generalized inertia matrix remains fixed because every link mass is fixed','Each link must gain or lose physical mass for the joint inertia to change','Only the gravity vector can change; inertial coupling is independent of configuration'],0,'Joint-space inertia depends on geometry and mass distribution relative to moving joint axes, not only on each link’s fixed mass.',['This separates generalized inertia from body mass.','Fixed masses do not imply fixed geometry about joint axes.','No physical mass transfer is required.','Inertial coupling can also vary with configuration.'])
add(698,'robot-dynamics-terms','Identify the velocity-dependent dynamics term','In τ=M(Θ)Θ̈+V(Θ,Θ̇)+G(Θ), which term represents the Coriolis and centrifugal/centripetal velocity coupling in the stated rigid-body model?', ['V(Θ,Θ̇)','G(Θ)','M(Θ) by itself','The reference acceleration Θ̈_d'],0,'V contains the stated velocity-dependent coupling; G is gravity and M multiplies the actual generalized acceleration.',['This is the velocity-coupling term.','Gravity depends on configuration, not velocity in this model.','M is the inertia matrix, not a torque vector by itself.','The desired acceleration is a reference, not the plant velocity-coupling term.'],typ='definition')
add(698,'mass-matrix-properties','Use the rigid manipulator mass-matrix property','For independent generalized coordinates of the usual nonsingular rigid manipulator model, which mass-matrix description is appropriate?', ['Symmetric positive definite, and generally configuration-dependent','Diagonal and configuration-independent for every coupled manipulator','Skew-symmetric with zero kinetic energy for every velocity','A column vector with one gravity value per joint'],0,'The quadratic kinetic-energy form uses a symmetric positive-definite inertia matrix; coupling generally permits off-diagonal elements.',['This is the stated property under the coordinate/model assumptions.','Coupled manipulators need not have diagonal or fixed inertia.','Skew symmetry would make the quadratic form zero.','Gravity is a separate vector.'],assumptions=['Use independent rigid generalized coordinates without a singular redundant coordinate representation.'])
add(698,'torque-convention','Separate actuator input from external torque','The slide labels τ as external torque; to model actuator torque τ_a and assisting contact torque τ_ext separately, which consistent equation should be stated?', ['MΘ̈+V+G=τ_a+τ_ext','MΘ̈+V+G=τ_a while τ_ext is silently included in τ_a without explanation','MΘ̈+V+G=τ_a−τ_ext although positive τ_ext is defined to assist positive motion','MΘ̈+V+G=τ_ext with no actuator input even while the motor drives the joint'],0,'With the declared assisting-positive contact convention, both actuator and external torques enter the right side; their meanings must not be conflated.',['This explicitly states both channels and their signs.','This hides the contact input inside the actuator variable.','This contradicts the declared assisting-positive sign.','This omits an explicitly present driving input.'],assumptions=['Positive external torque assists the positive generalized coordinate direction.'],conflict='Page698 labels τ External Torque while describing the conventional total-input rigid-body equation; actuator and disturbance channels require an explicit convention.')
add([698,699],'payload-effects','Trace a payload change beyond a disturbance term','A robot rigidly grasps an additional mass; which model update is generally needed?', ['Update inertia and gravity terms, and velocity coupling where affected','Add only a constant disturbance torque while leaving all model matrices unchanged','Change the gravity term only because grasped mass cannot affect acceleration torque','Change the motor winding resistance only because the payload is outside the robot'],0,'A carried payload changes the moving mass distribution and gravitational load; it is not generally captured by a single constant external torque.',['This accounts for the payload’s dynamic and gravitational effects.','A constant disturbance cannot generally represent configuration- and acceleration-dependent effects.','Added moving mass changes inertia as well as gravity.','Winding resistance is not the direct rigid-body payload model.'],typ='scenario')
add(699,'time-variation-scope','Qualify the fixed-controller failure claim','A controller was designed for an empty arm and the arm now carries a payload; what conclusion follows without a new stability analysis?', ['Tracking or stability margins may degrade, but failure is not inevitable','The controller must become unstable for every nonzero payload','The controller remains exactly unchanged in performance because gains are fixed','The payload affects only sensor calibration, not the controlled dynamics'],0,'Model mismatch can degrade control, but a robust controller or a small admissible payload may still meet requirements.',['This states the risk without an unsupported universal outcome.','Instability depends on controller, plant and payload size.','Fixed gains do not guarantee unchanged dynamics or tracking.','A payload changes the physical dynamics.'],typ='scenario',conflict='Page699 says an empty-arm fixed controller fails with payload; this is a risk statement, not a universal theorem.')
add(699,'thermal-current-control','Separate winding resistance from regulated torque','Winding resistance rises as a motor heats; with an ideal current regulator still within its voltage limit, what is the most direct consequence at the same current command?', ['More voltage is required to maintain the same current and electromagnetic torque','The electromagnetic torque must fall in inverse proportion to resistance despite identical regulated current','The rotor inertia rises in direct proportion to winding resistance','The current must become zero even though adequate drive voltage remains available'],0,'For the same current and torque constant, electromagnetic torque is unchanged; the resistive voltage drop increases.',['This follows the current-regulated assumption.','Torque depends on current under the stated model, not resistance alone.','Electrical resistance does not directly redefine rotor inertia.','The voltage-headroom assumption rules out this forced loss of current.'],typ='scenario',assumptions=['The torque constant stays fixed and the ideal regulator has sufficient voltage and thermal operating margin.'])
add(700,'configuration-photo','Interpret the configuration photographs','What can the three KUKA configuration photographs support without masses, dimensions and joint-axis data?', ['An illustration that configuration can alter effective inertia, not a numerical ranking of all three inertias','A numerical proof that the middle pose has exactly twice the inertia of the first','A conclusion that the robot’s total physical mass changes between poses','A proof that gravity torque is identical at every illustrated joint and pose'],0,'The photographs show geometry changes, but do not supply the quantitative data needed to calculate or rank every joint inertia.',['This is the appropriate qualitative use of the image.','No such ratio is provided.','Changing pose does not itself change total mass.','Gravity torque can depend on pose and joint geometry.'],typ='diagram')
add(701,'moving-linearization','Interpret a moving operating-point model','A nonlinear autonomous robot is linearized along a changing reference trajectory; what is the resulting perturbation model generally like?', ['Linear with coefficients that can vary with time along that trajectory','Exactly equal to the full nonlinear system for arbitrarily large deviations','Necessarily time-invariant because the original equations have no explicit time variable','A model with no dependence on the chosen operating trajectory'],0,'The Jacobians are evaluated at a trajectory-dependent operating point, so the local linear coefficients can vary in time even when the original model is autonomous.',['This distinguishes trajectory-dependent linearization from explicit time dependence of the original equations.','Linearization is generally a local approximation.','State-dependent Jacobians can vary along the trajectory.','Changing the operating trajectory generally changes the linearization.'])
add(701,'local-model-validity','Choose when to reconsider a local linear model','A linear model was derived near one arm pose, but the planned motion crosses a wide region with strongly changing inertia; what is the justified next step?', ['Check the local model’s validity and use an appropriate moving or nonlinear model if needed','Assume the original local model is exact because it is linear','Reject every possible use of linear control, including a locally valid controller','Replace changing inertia with a new link mass inferred solely from joint angle'],0,'A local approximation must be checked over the intended operating range; neither exact global validity nor a universal ban on linear methods follows.',['This matches the limitation of a local approximation.','Linearity does not make the approximation globally exact.','Local linear methods can still be useful within their assumptions.','Generalized inertia changes do not imply changing physical link mass.'],typ='scenario')
add(702,'normalized-fixed-gains','Distinguish physical and normalized gains','After exact model cancellation reduces the joint to ẍ=f′, can fixed positive normalized servo gains be used?', ['Yes; fixed gains can set the ideal normalized error dynamics even though the physical compensation depends on state','No; every controller gain must vary explicitly with time whenever the original plant is nonlinear','Yes; therefore the physical input no longer depends on measured state','No; cancellation can remove gravity only, never inertia or velocity terms'],0,'The state-dependent model part and fixed normalized servo part have different roles.',['This is the partitioned-control distinction.','Nonlinearity alone does not prohibit fixed normalized servo gains.','The model-compensation term still depends on measured state.','The ideal matched partition includes inertia and velocity terms as well.'],conflict='The slide contrasts fixed gains and time-varying plant coefficients; fixed normalized gains after exact cancellation must not be confused with unchanged physical gains on the raw plant.')
add(702,'cancellation-assumptions','Identify a condition needed for exact cancellation','Which situation invalidates the stated ideal cancellation argument without additional treatment?', ['The actuator saturates so the requested compensating input is not applied','The positive-definite inertia matrix has nonzero off-diagonal elements but is known and inverted exactly','The desired trajectory is smooth and its acceleration is supplied consistently','The normalized servo gains are fixed while the exact model term changes with state'],0,'Exact algebra assumes the demanded input reaches the plant; saturation leaves a residual not removed by the derivation.',['This directly violates the ideal applied-input assumption.','Known coupling can be included in full-matrix compensation.','Consistent reference derivatives support the derivation.','That division of roles is precisely the partitioned design.'],typ='scenario')
add(703,'cubic-spring-law','Distinguish a cubic spring coefficient from stiffness','For restoring-force magnitude f_s=q x³, what are the units of q and the local tangent stiffness?', ['q has units N/m³ and tangent stiffness is 3q x²','q has units N/m and tangent stiffness is q','q has units N/m³ and tangent stiffness is q x²','q has units N·m³ and tangent stiffness is 3q x'],0,'Force requires q to have units N/m³; differentiating qx³ gives the tangent stiffness 3qx², while qx² is the secant ratio for nonzero x.',['Both units and derivative are correct.','These are the coefficient and stiffness of a linear spring, not this cubic law.','The expression is the secant ratio rather than tangent stiffness.','Both the coefficient units and derivative are incorrect.'],typ='derivation',steps=['Use [q][x]³=N to obtain [q]=N/m³.','Differentiate f_s with respect to x to obtain 3qx².'],formulas=[formula('f_s=qx³; k_t=df_s/dx=3qx²',{'f_s':'restoring-force magnitude with signed displacement','q':'cubic spring coefficient','x':'displacement','k_t':'tangent stiffness'},{'f_s':'N','q':'N/m³','x':'m','k_t':'N/m'})])
add(703,'cubic-spring-scaling','Evaluate the cubic spring scaling','For q>0, displacement changes from x to 2x with x≠0; how do restoring-force magnitude and tangent stiffness change?', ['Force magnitude multiplies by 8 and tangent stiffness by 4','Force magnitude and tangent stiffness both multiply by 2','Force magnitude multiplies by 4 and tangent stiffness by 8','Force magnitude multiplies by 8 and tangent stiffness stays constant'],0,'The cubic force scales as x³ while its derivative scales as x².',['This applies the two different powers.','This treats both expressions as linear in displacement.','This swaps the cubic and quadratic powers.','The tangent stiffness is not constant for a cubic spring.'],typ='numerical',steps=['Evaluate (2x)³/x³=8.','Evaluate (2x)²/x²=4.'])
add(703,'cubic-graph','Read the cubic restoring-force graph','For the illustrated law f_s=x³ in consistent units, which point and symmetry agree with the plotted curve?', ['(x,f_s)=(-2,-8), with odd symmetry about the origin','(x,f_s)=(-2,8), with even symmetry about the vertical axis','(x,f_s)=(-2,-2), with a constant slope of one','(x,f_s)=(-2,-4), with a quadratic negative branch'],0,'Cubing a negative displacement preserves its negative sign and f_s(-x)=-f_s(x).',['This matches the cubic graph.','A cubic is odd rather than even.','This describes the linear law, not the cubic curve.','The value is -8, not -4.'],typ='diagram',assumptions=['Use the illustrative coefficient q=1 in consistent force/displacement units.'])
add(704,'nonlinear-force-balance','Interpret signs in the cubic spring plant','In m ẍ+b ẋ+q x³=f with positive x and ẋ, which physical forces oppose the positive applied input?', ['The viscous force −b ẋ and spring force −q x³','The viscous force +b ẋ and spring force +q x³','Only the spring force, because viscous damping assists positive motion','Only the viscous force, because the cubic spring always assists positive displacement'],0,'Moving the resisting terms to the right gives m ẍ=f−b ẋ−q x³.',['Both oppose positive motion/displacement under the stated signs.','These are the LHS resisting magnitudes, not forces in the positive input direction.','Positive viscous damping opposes positive velocity.','A positive cubic restoring coefficient opposes positive displacement.'],assumptions=['m,b,q are positive and the input force is positive to the right.'])
add(704,'physical-stiffness-gains','Convert physical closed-loop stiffness to normalized gains','For a matched mass m=2 kg and requested physical error stiffness k_CL=18 N/m, which normalized gains produce critical damping?', ['k_p=9 s⁻² and k_v=6 s⁻¹','k_p=18 s⁻² and k_v=2√18 s⁻¹','k_p=9 s⁻² and k_v=3 s⁻¹','k_p=36 s⁻² and k_v=12 s⁻¹'],0,'Dividing the desired physical error equation by m gives k_p=k_CL/m=9; critical damping requires k_v=2√k_p=6.',['Both normalization and critical damping are correct.','This omits division by mass.','This omits the factor two in critical damping.','This multiplies stiffness by mass instead of dividing.'],typ='numerical',steps=['Compute k_p=18/2=9 s⁻².','Compute k_v=2√9=6 s⁻¹.'],formulas=[formula('k_p=k_CL/m; k_v=2√k_p',{'k_p':'normalized stiffness gain','k_v':'normalized damping gain','k_CL':'physical error stiffness','m':'mass'},{'k_p':'s⁻²','k_v':'s⁻¹','k_CL':'N/m','m':'kg'})])
add(705,'partition-units','Interpret the normalized servo signal','In f=m f′+b ẋ+q x³, what are the units and role of f′?', ['Acceleration in m/s², which is multiplied by mass before adding force compensation','Force in N, which is multiplied by mass to obtain another force','Velocity in m/s, which directly cancels the cubic restoring force','Position in m, which is added directly to the external force'],0,'The product m f′ must have force units, so f′ is an acceleration command.',['This makes all force terms dimensionally consistent.','Mass times force would not have force units.','Velocity alone has the wrong units for this mass product.','Position has the wrong units for direct force addition.'],typ='definition')
add([705,706],'cubic-cancellation','Derive the normalized cubic plant','Substitute f=m f′+b ẋ+q x³ into m ẍ+b ẋ+q x³=f; what remains under the matched-model assumptions?', ['ẍ=f′','ẍ=f′−(b ẋ+q x³)/m','m ẍ=f′','ẍ=m f′'],0,'The same viscous and cubic terms cancel from both sides, leaving m ẍ=m f′ and then ẍ=f′.',['This follows after cancellation and division by nonzero mass.','This subtracts terms that have already been canceled.','This omits the mass multiplying f′ in the applied force.','This fails to divide both sides by mass.'],typ='derivation',assumptions=matched,steps=['Cancel identical b ẋ and q x³ terms.','Obtain m ẍ=m f′.','Divide by m>0.'],formulas=[servo])
add(705,'partition-force-calculation','Calculate a compensated force','For m=2 kg, b=0.5 N·s/m, q=4 N/m³, x=0.5 m, ẋ=−2 m/s and f′=3 m/s², what input f implements the matched partition?', ['5.5 N','6.5 N','7.5 N','7.0 N'],0,'The inertia term is 6 N, the viscous term is −1 N and the cubic term is 0.5 N, giving 5.5 N.',['This retains the negative velocity sign and cubic displacement.','This omits the viscous term.','This reverses the viscous sign.','This uses qx=2 N instead of qx³=0.5 N.'],typ='numerical',steps=['Compute m f′=2×3=6 N.','Compute b ẋ=0.5×(−2)=−1 N.','Compute q x³=4×0.5³=0.5 N.','Add 6−1+0.5=5.5 N.'])
add(706,'desired-minus-actual-error','Derive the homogeneous tracking-error equation','With e=x_d−x and ẍ=ẍ_d+k_v ė+k_p e, which error equation follows?', ['ë+k_v ė+k_p e=0','ë−k_v ė−k_p e=0','ë+k_v ė−k_p e=0','ë=ẍ_d+k_v ė+k_p e'],0,'Differentiate the declared error twice: ë=ẍ_d−ẍ=−k_v ė−k_p e.',['This preserves the declared desired-minus-actual convention.','This reverses both feedback signs.','This reverses the position-feedback sign only.','This confuses the actual acceleration equation with the error equation.'],typ='derivation',steps=['Differentiate e=x_d−x twice.','Substitute the actual acceleration.','Cancel desired acceleration and move feedback terms to the left.'],formulas=[servo])
add(706,'compensation-diagram','Trace measured signals in the partitioned-control diagram','In the cubic-plant block diagram, which measured signals feed the model-compensation term β?', ['Actual position x and actual velocity ẋ','Desired position x_d and desired velocity ẋ_d only','The position error e and desired acceleration only','The commanded force f and its time integral only'],0,'The plant’s actual b ẋ+q x³ terms are canceled using measured actual state, while desired quantities enter the servo calculation.',['This reconstructs the actual plant terms.','Using only desired state does not generally cancel actual state terms.','Errors alone do not supply the displayed β expression without reconstructing actual state.','The displayed β does not use force integration.'],typ='diagram')
add(707,'coulomb-viscous-law','Distinguish viscous and Coulomb friction at nonzero speed','For constant positive coefficients, which comparison is correct away from zero velocity?', ['Viscous resistance magnitude grows with |velocity|; ideal Coulomb resistance magnitude is constant','Both viscous and ideal Coulomb resistance magnitudes grow linearly with |velocity|','Viscous resistance magnitude is constant; Coulomb resistance is proportional to velocity squared','Both resistance forces always point in the positive coordinate direction'],0,'Viscous resistance is proportional to velocity, while the ideal Coulomb term changes sign but has fixed nonzero-speed magnitude.',['This separates the two stated laws.','Only the viscous law is proportional to speed.','This reverses the first law and invents a quadratic second law.','Resistance opposes motion rather than having a fixed coordinate direction.'])
add(707,'coulomb-zero-speed','Separate the printed sign law from static friction','The printed classroom definition gives sgn(0)=0, but the plot shows filled endpoints at both ±b_c; which interpretation should be used explicitly?', ['Use the declared single-valued sign law for the code, while noting that the graph and real static-friction behavior need separate qualification','Treat sgn(0) as simultaneously +1 and −1 in an ordinary scalar calculation','Infer that real static friction must always vanish whenever measured speed is zero','Replace every nonzero-speed Coulomb force by zero because the graph endpoints conflict'],0,'The numerical sign function uses zero at zero; a static-friction interval is a different model and the plotted endpoints do not define two simultaneous scalar outputs.',['This preserves the stated code law and flags the discrepancy.','An ordinary scalar sign function cannot return both values simultaneously.','Real stiction can balance a range of applied forces at rest.','The zero-speed discrepancy does not erase the nonzero-speed law.'],conflict='Page707 plots filled zero-speed endpoints at ±b_c while the displayed piecewise definition states sgn(0)=0.')
add(707,'coulomb-force-direction','Determine the physical friction direction','For a Coulomb magnitude b_c=0.4 N and velocity −2 m/s, what is the physical friction force on the mass when resistance enters the equation’s left side as b_c sgn(ẋ)?', ['+0.4 N','−0.4 N','−0.8 N','0 N'],0,'The physical force is −b_c sgn(ẋ); negative velocity gives a positive resisting force.',['This opposes the negative motion.','This is the LHS signed resistance term, not the physical RHS force.','This incorrectly multiplies Coulomb magnitude by speed.','The velocity is not zero.'],typ='numerical',steps=['Evaluate sgn(−2)=−1.','Compute physical force −0.4×(−1)=+0.4 N.'])
add(708,'coulomb-plant-distinction','Identify the terms in the second spring example','Which equation is the Coulomb-plus-linear-spring plant used after the cubic spring example?', ['m ẍ+b_c sgn(ẋ)+k x=f','m ẍ+b ẋ+q x³=f','m ẍ+b_c ẋ³+k x²=f','m ẍ+b ẋ+b_c sgn(ẋ)+q x³=f as the unchanged printed model'],0,'The second example uses Coulomb friction and a linear spring; it does not silently retain the earlier viscous/cubic terms.',['This matches the printed second plant.','This is the earlier viscous/cubic plant.','These powers do not match either stated law.','This adds and mixes terms not present in the printed second example.'],typ='match')
add([709,710],'coulomb-cancellation','Select the compensating term for the Coulomb plant','For m ẍ+b_c sgn(ẋ)+k x=f and f=m f′+β, which β gives the displayed exact cancellation?', ['b_c sgn(ẋ)+k x','−b_c sgn(ẋ)−k x','b_c ẋ+k x','b_c sgn(ẋ)+k x_d'],0,'The positive compensation reproduces the actual LHS resisting terms so they cancel after substitution.',['This matches both actual plant terms.','This doubles their opposing effect instead of canceling them.','This replaces the Coulomb law by a viscous law.','Desired position need not equal the actual position in the spring term.'],typ='derivation',assumptions=matched,steps=['Substitute f=m f′+β.','Choose β equal to the actual non-inertial LHS terms.','Cancel them to obtain ẍ=f′.'])
add(709,'coulomb-input-numerical','Compute the Coulomb and spring compensation','Use m=2 kg, f′=3 m/s², b_c=0.4 N, ẋ=−2 m/s, k=5 N/m and x=0.1 m; what is f=m f′+b_c sgn(ẋ)+k x?', ['6.1 N','6.9 N','5.7 N','6.5 N'],0,'The inertia term is 6 N, Coulomb compensation is −0.4 N and spring compensation is 0.5 N, so the sum is 6.1 N.',['This follows the stated sign law.','This reverses the Coulomb compensation sign.','This incorrectly scales Coulomb magnitude by velocity.','This omits Coulomb compensation.'],typ='numerical',steps=['Calculate 2×3=6 N.','Calculate 0.4×sgn(−2)=−0.4 N.','Calculate 5×0.1=0.5 N.','Add the three terms.'])
add([710,711],'friction-mismatch','Derive the residual from an underestimated Coulomb coefficient','The actual plant uses b_c, but compensation uses b̂_c; with e=x_d−x and all other terms matched, which residual error equation is correct?', ['ë+k_v ė+k_p e=(b_c−b̂_c)sgn(ẋ)/m','ë+k_v ė+k_p e=(b̂_c−b_c)sgn(ẋ)/m','ë+k_v ė+k_p e=b_c−b̂_c without a sign or mass factor','ë+k_v ė+k_p e=0 for every coefficient estimate'],0,'Actual acceleration equals f′+(b̂_c−b_c)sgn(ẋ)/m; subtracting it from desired acceleration reverses that residual sign in the error equation.',['This follows the declared error convention and units.','This is the residual in actual acceleration, not error acceleration.','The missing sign and mass make the force-to-acceleration conversion incomplete.','Exact cancellation requires matching the coefficient.'],typ='derivation',difficulty='medium',assumptions=['Only the Coulomb coefficient is mismatched; mass and spring compensation are exact.'],steps=['Substitute m f′+b̂_c sgn(ẋ)+k x into the actual plant.','Solve ẍ=f′+(b̂_c−b_c)sgn(ẋ)/m.','Use ë=ẍ_d−ẍ and the normalized servo expression.'])
add(711,'critical-error-poles','Find critical damping of the normalized error equation','For ë+8ė+16e=0, what are the poles and damping classification?', ['A repeated pole at −4 s⁻¹, critically damped','Poles at −8 and −16 s⁻¹, overdamped','Poles at ±4i s⁻¹, undamped','A repeated pole at +4 s⁻¹, unstable'],0,'The characteristic polynomial s²+8s+16=(s+4)² has a repeated negative root.',['This is the correct factorization.','Polynomial coefficients are not themselves the roots.','The damping term is nonzero.','The root sign is negative.'],typ='numerical',steps=['Write s²+8s+16=0.','Factor as (s+4)²=0.','Read the repeated negative pole and critical damping.'])
add([712,713],'pendulum-angle-reference','Use the pendulum angle convention','The source measures θ counterclockwise from the horizontal right direction; which gravity term belongs on the left side of its point-mass equation?', ['+mgl cosθ','+mgl sinθ for the same unchanged angle reference','−mgl cosθ while positive actuator torque is counterclockwise','+mg/l cosθ'],0,'Gravity produces physical clockwise torque −mgl cosθ, so moving it to the left gives +mgl cosθ.',['This matches the horizontal angle reference and sign convention.','A sine expression requires a shifted angle reference.','This reverses the restoring torque’s LHS sign.','The lever arm multiplies the weight rather than dividing it.'],typ='diagram',assumptions=['The rigid link is massless, its point mass is at distance l, and positive actuator torque increases θ.'],formulas=[angular])
add(712,'pendulum-inertia','Separate nonlinear dynamics from varying inertia','For the fixed point mass m at the end of a massless rigid link l in this single-joint example, why is the model nonlinear?', ['Gravity and Coulomb terms are nonlinear even though I=ml² is constant','The inertia I=ml² must vary with angle in this fixed-length one-link model','Its differential equation must have order greater than two because gravity is nonlinear','The point mass must change during every revolution'],0,'A nonlinear second-order model can have constant inertia; cosθ and sign-dependent friction already introduce nonlinearity.',['This distinguishes coefficient variation, nonlinearity and equation order.','The stated fixed m and l give constant I.','Nonlinearity does not itself increase differential-equation order.','The example does not require changing physical mass.'])
add(713,'pendulum-holding-torque','Calculate gravity holding torque at two poses','With m=1 kg, l=1 m and g=9.81 m/s², at rest under the printed sgn(0)=0 law, what gravity-holding torques are needed at θ=0 and θ=π/2?', ['9.81 N·m and 0 N·m','0 N·m and 9.81 N·m','−9.81 N·m and 0 N·m','9.81 N·m and 9.81 N·m'],0,'The holding input is mgl cosθ; cosine is one at the horizontal pose and zero at the upright pose.',['This uses the source’s angle reference.','This uses a sine law without changing the angle reference.','The holding actuator torque opposes the negative gravity torque.','Gravity’s moment arm changes with angle.'],typ='numerical',steps=['Set velocity and acceleration to zero and use sgn(0)=0.','Evaluate 9.81cos0=9.81 N·m.','Evaluate 9.81cos(π/2)=0 N·m.'],assumptions=['Use the printed single-valued Coulomb model, not a separate static-friction interval.'])
add([713,714],'pendulum-compensation','Choose the pendulum model term','For the printed pendulum plant, which β must be added to I f′ to cancel the actual model terms?', ['vθ̇+c sgn(θ̇)+mgl cosθ','vθ̇_d+c sgn(θ̇_d)+mgl cosθ_d','−vθ̇−c sgn(θ̇)−mgl cosθ','vθ̇+c sinθ+mgl sgn(θ̇)'],0,'Exact model cancellation uses the actual measured velocity and angle in each corresponding physical term.',['This matches the actual plant terms.','Desired-state terms generally do not cancel actual-state terms away from perfect tracking.','These signs reinforce rather than cancel the LHS resistance terms.','This swaps the Coulomb and gravity dependencies.'],typ='derivation',assumptions=matched,steps=['Write τ=I f′+β.','Match β to the three non-inertial LHS terms.','Cancel them and divide by I>0.'],formulas=[angular])
add([714,715],'desired-acceleration-typo','Resolve the missing derivative dot explicitly','Page715’s top line shows only one desired-angle dot, but the preceding equation and diagram specify desired angular acceleration; which normalized servo is dimensionally consistent?', ['f′=θ̈_d+k_v ė+k_p e','f′=θ̇_d+k_v ė+k_p e with no unit conversion','f′=θ_d+k_v ė+k_p e with θ_d in radians','f′=θ̈_d+k_v e+k_p ė with the same gain units'],0,'The feedforward term must have angular-acceleration units, matching both feedback terms when k_v has s⁻¹ and k_p has s⁻².',['This matches the surrounding equations, diagram and units.','Desired velocity has different units from acceleration.','Desired angle also has different units.','Swapping error derivatives while keeping gain units breaks dimensional consistency.'],conflict='The actual page715 top substitution line has one dot on desired theta; page714 and the block diagram have two, supporting an explicitly identified source typo.',assumptions=['k_v has units s⁻¹, k_p has units s⁻², and e is an angular error.'])
add(715,'pendulum-block-diagram','Trace the torque partition in the block diagram','The pendulum diagram labels the normalized servo τ′; what operation turns it into the physical actuator torque?', ['Multiply by ml² and then add the modeled friction and gravity torque','Add ml² directly to τ′ without multiplication','Multiply by the gravitational torque and then divide by friction','Treat τ′ as already measured in N·m and omit the inertia block'],0,'Despite the τ′ label, the normalized servo has angular-acceleration units; inertia multiplication produces torque before adding β.',['This matches the diagram and dimensions.','Adding inertia to acceleration is dimensionally invalid.','These operations are not the partition shown.','The label does not change the signal’s units or remove the inertia block.'],typ='diagram')
add(716,'constant-reference-code','Read the desired trajectory function','The function returns deg2rad(90.0), 0.0, 0.0 for every t; what reference does it command?', ['A fixed upright angle π/2 rad with zero desired velocity and acceleration','A ramp of 90 degrees per second with zero acceleration','A fixed angle of 90 rad with zero velocity and acceleration','A sinusoidal angle whose period is 90 seconds'],0,'The conversion returns a constant π/2 radians; the two derivative outputs are zero.',['This matches all three returned values.','The first value is position, not a speed command.','deg2rad converts 90 degrees to π/2 radians.','The function contains no time-dependent sinusoid.'],typ='code_output')
add(716,'gain-parameter-code','Read the physical and normalized parameters','The code sets m=1, l=1, I=m*l**2, v=0.6, c=0.4, kp=16 and kv=8; which statement matches these roles?', ['I=1 kg·m², v is viscous damping, c is Coulomb magnitude, and kp/kv are normalized servo gains','I=1 N·m, v is desired speed, c is gravitational acceleration, and kp/kv are link lengths','I=2 kg·m², v and c are both desired accelerations, and kp=kv²','I=1 kg·m², v is Coulomb magnitude and c is viscous damping, with all parameters in the same units'],0,'The code follows the inertia, friction and normalized-gain definitions of the displayed model.',['This preserves the distinct parameter meanings and units.','These units and roles do not match the model.','m*l² equals one, and the remaining interpretations are incorrect.','The two friction roles are reversed and their units differ.'],typ='code')
add(717,'controller-return-values','Interpret the controller return tuple','What does control_torque return in the shown code, in order?', ['Actuator torque, position error, velocity error, normalized commanded angular acceleration','Angle, angular velocity, actual acceleration, integration time','Actuator torque, actual angle, actual speed, gravitational torque','Normalized acceleration, actuator torque, desired angle, desired speed'],0,'The return statement is tau,e,e_dot,f_prime; these diagnostic values are not the plant state.',['This matches the stated variable definitions and return order.','This describes a different state/integration tuple.','e and e_dot are errors, not actual state values.','This rearranges and replaces the return values.'],typ='code')
add(717,'controller-code-error-sign','Calculate the controller error signs','At desired angle π/2 rad with zero desired speed, the actual state is θ=π/6 rad and θ̇=0.5 rad/s; what are e and e_dot in the code?', ['π/3 rad and −0.5 rad/s','−π/3 rad and +0.5 rad/s','2π/3 rad and +0.5 rad/s','π/3 rad and +0.5 rad/s'],0,'Both errors are desired minus actual: π/2−π/6=π/3 and 0−0.5=−0.5.',['This uses the code’s convention for both errors.','This uses actual minus desired.','The angle subtraction and speed sign are both wrong.','The position error is correct but velocity-error sign is reversed.'],typ='numerical',steps=['Subtract actual angle from desired angle.','Subtract actual speed from zero desired speed.'])
add(717,'radians-in-code','Prevent a degree-radian gravity error','When evaluating the shown m*g*l*np.cos(theta), how should a measured 90-degree angle be passed?', ['Convert it to π/2 radians before np.cos','Pass the number 90 directly because the desired angle was written as 90.0 before conversion','Multiply 90 by 180/π and pass that result','Apply np.sign(90) instead of np.cos to avoid unit conversion'],0,'NumPy trigonometric functions use radians, and the source explicitly converts the desired angle with deg2rad.',['This produces the correct near-zero cosine at upright.','np.cos(90) interprets 90 radians, not 90 degrees.','This converts in the wrong direction.','The sign function is not the gravity-angle law.'],typ='code')
add(718,'state-derivative-order','Read the ODE state and derivative order','For x=[theta,theta_dot], which vector must plant_dynamics return to solve the shown second-order motion?', ['[theta_dot,theta_ddot]','[theta,theta_dot]','[theta_ddot,theta_dot]','[tau,theta_ddot]'],0,'The derivative of angle is angular velocity and the derivative of angular velocity is angular acceleration.',['This is the first-order state representation.','This returns the state rather than its derivative.','This reverses the derivative order.','Torque is not the derivative of angle.'],typ='code')
add(718,'discarded-diagnostics','Interpret the underscore assignments','What is the purpose of tau,_,_,_=control_torque(t,x) in plant_dynamics?', ['Use the torque while not using the other three returned diagnostics in that calculation','Force the other three returned values to become zero inside control_torque','Ask solve_ivp to integrate four additional unnamed state variables','Change the controller’s return tuple so it contains only one value'],0,'Tuple unpacking receives all four values; repeated underscore is a conventional name for unused values, not an operation that changes the function.',['This describes Python assignment and the intended use.','Unpacking does not modify the returned values inside the function.','These assignments do not define ODE state variables.','The function still returns four values.'],typ='code')
add(718,'numerical-tolerance-scope','Interpret the solver tolerances','What does rtol=atol=1e-8 in the displayed solve_ivp call establish by itself?', ['Requested local numerical error tolerances, not proof that the physical model or hardware controller is accurate','A guaranteed physical tracking error below 1e-8 radians for any real robot','An exactly error-free numerical trajectory at every sample','A maximum motor torque of 1e-8 N·m'],0,'Solver tolerances guide adaptive numerical error control; they do not validate the model, measurements, actuator limits or hardware.',['This is the relevant numerical scope.','Physical tracking accuracy needs additional assumptions and evidence.','Finite-precision numerical integration is not exact.','The tolerance arguments are not actuator limits.'],typ='code')
add([716,718],'snippet-reconstruction','Identify what is missing from the displayed executable snippet','Which set must be supplied to execute the displayed integration as a standalone reconstruction?', ['Required imports and definitions of t0,tf,x0,t_eval','A replacement for the already printed plant_dynamics function only','A new gravitational law because np.cos cannot accept a scalar','A mandatory animation callback even when only integrating the state'],0,'The screenshots show controller and plant functions but omit the import and integration setup definitions.',['These referenced names need definitions.','The plant function is already present and is not the only required context.','np.cos accepts scalar angles.','Animation is not required to solve the ODE.'],typ='code',conflict='The source snippets omit initialization/imports and plotting/animation code; reconstruction must identify supplied context rather than claim literal standalone source execution.')
add([716,719,720],'initial-error-calculation','Reconstruct the plotted initial tracking error','For an explicitly supplied reproduction starting at −20 degrees with desired angle 90 degrees, what is the initial desired-minus-actual error in radians?', ['110π/180≈1.91986 rad','70π/180≈1.22173 rad','−110π/180≈−1.91986 rad','110 rad'],0,'Subtracting −20 from 90 gives 110 degrees, which must be converted to radians.',['This agrees with the static frame’s approximately1.9199rad error.','This subtracts the magnitude instead of the negative angle.','This reverses the error convention.','This omits the degree-to-radian conversion.'],typ='numerical',assumptions=['The initial state is supplied for the reconstruction; the source plots suggest it but the screenshots do not print x0.'],steps=['Compute 90−(−20)=110 degrees.','Multiply by π/180.'])
add([717,719,720],'initial-torque-calculation','Reproduce the displayed initial pendulum torque','Use the code parameters I=1,v=0.6,c=0.4,m=l=1,g=9.81,kp=16,kv=8 with θ=−20 degrees, θ̇=0, θ_d=90 degrees and zero desired derivatives; what is the initial torque?', ['Approximately39.94 N·m','Approximately30.72 N·m','Approximately40.34 N·m','Approximately21.50 N·m'],0,'The normalized acceleration is16×110π/180≈30.7178; zero-speed viscous/Coulomb terms vanish, and gravity adds9.81cos(−20°)≈9.2184, giving39.9362 N·m.',['This includes the correct gravity and zero-speed sign law.','This omits gravity compensation.','This adds a positive Coulomb term even though np.sign(0)=0.','This subtracts rather than adds the gravity compensation.'],typ='numerical',difficulty='medium',assumptions=['Use the explicitly supplied initial state and the printed np.sign(0)=0 law.','Convert angles to radians before trigonometry.'],steps=['Compute e0=110π/180≈1.919862rad and e_dot0=0.','Compute f′0=16e0≈30.717795rad/s².','Compute gravity compensation9.81cos(−20π/180)≈9.218385N·m.','Add I f′0 and gravity; the two zero-speed friction terms vanish.'],formulas=[angular])
add(719,'critical-step-response','Use the full critical-damping initial-condition solution','For ë+8ė+16e=0 with e(0)=e0 and ė(0)=0, which error trajectory satisfies both initial conditions?', ['e(t)=e0(1+4t)e^(−4t)','e(t)=e0e^(−4t)','e(t)=e0(1−4t)e^(−4t)','e(t)=e0cos(4t)'],0,'A repeated root−4 gives (A+Bt)e^(−4t); e(0)=e0 sets A=e0 and zero initial derivative sets B=4e0.',['This satisfies both the equation and initial conditions.','Its initial derivative is−4e0 rather than zero.','Its initial derivative is−8e0 rather than zero.','This solves an undamped oscillation equation instead.'],typ='derivation',difficulty='medium',steps=['Factor the characteristic polynomial as(s+4)².','Write e=(A+Bt)e^(−4t).','Set A=e0 and B−4A=0.'],formulas=[formula('e(t)=e0(1+ω_n t)e^(−ω_n t)',{'e':'position error','e0':'initial position error','ω_n':'natural frequency of the repeated negative pole','t':'time'},{'e,e0':'rad','ω_n':'s⁻¹','t':'s'},['Critical damping, zero initial error derivative, constant desired angle.'])])
add(719,'peak-speed-response','Find the peak speed of the matched critical response','For e0=110π/180 rad and the ideal response θ̇(t)=16e0 t e^(−4t), when is the positive speed maximal and what is its value?', ['At0.25s, approximately2.825rad/s','At1s, approximately2.825rad/s','At0.25s, approximately30.718rad/s','At0s, approximately1.920rad/s'],0,'Differentiation gives16e0e^(−4t)(1−4t); the maximum occurs at t=1/4 and has value4e0/e≈2.82511.',['This matches the derivative condition and value.','One second is past the maximum.','30.718 is the initial acceleration, not the peak speed.','The supplied initial speed is zero.'],typ='derivation',difficulty='medium',steps=['Differentiate the speed expression.','Set1−4t=0 to obtain0.25s.','Evaluate16e0×0.25×e^(−1)=4e0/e.'],formulas=[formula('ω(t)=16e0 t exp(−4t); t_peak=1/4; ω_peak=4e0/exp(1)',{'ω':'angular speed','e0':'initial angle error','t':'time','t_peak':'time of peak speed','ω_peak':'maximum speed','4':'natural frequency in s⁻¹','16':'squared natural frequency in s⁻²'},{'ω,ω_peak':'rad/s','e0':'rad','t,t_peak':'s'})])
add(719,'plot-robustness-scope','State what the matched-model simulation does not establish','The plotted simulation uses the same model terms in controller and plant; which further claim is not established by those plots alone?', ['Robust performance under unmodeled payload changes and actuator saturation','Convergence of the displayed nominal trajectory over its shown interval','The shown initial error is positive under desired-minus-actual convention','The plotted torque changes during the transient'],0,'The plots demonstrate a particular nominal simulation, not untested mismatch, saturation or hardware cases.',['These require additional models or experiments.','This is visible in the nominal plots.','The displayed initial error is approximately1.92rad.','The torque curve visibly changes.'],typ='scenario')
add([707,717,719],'coulomb-near-equilibrium','Explain the ideal Coulomb torque near the final pose','In the matched model, θ approachesπ/2 while θ̇ stays positive but tends to zero; what happens to c*np.sign(theta_dot) before velocity becomes exactly zero?', ['It stays at+c, then the printed sign law gives0 if velocity is exactly zero','It continuously decreases in proportion to θ̇ because it is a viscous term','It becomes−c while θ̇ is still positive','It is zero throughout the approach because the target speed is zero'],0,'The ideal sign law depends on the sign of actual speed, not its small magnitude or desired speed; it is discontinuous at zero.',['This follows the printed numerical law.','That would be viscous friction, a different term.','A positive actual velocity has positive sign.','The code uses actual velocity in this term.'],assumptions=['Use the ideal printed sign law, not a smoothed or stiction model.'])
add(720,'animation-coordinate-map','Map the angle to the link endpoint','For a unit link measured counterclockwise from horizontal right, which endpoint corresponds to θ=−20 degrees?', ['Approximately(0.940,−0.342)m','Approximately(−0.342,0.940)m','Approximately(0.940,+0.342)m','Approximately(−0.940,−0.342)m'],0,'The horizontal reference gives x=lcosθ and y=lsinθ; the negative angle places the endpoint below the positive horizontal axis.',['This matches the reference and signs.','This swaps sine and cosine as if using a different reference.','This reverses the vertical sign.','This places the link in the wrong horizontal half-plane.'],typ='diagram',steps=['Use x=cos(−20°)≈0.93969m.','Use y=sin(−20°)≈−0.34202m.'])
add(720,'phase-portrait-axes','Read the phase portrait’s plotted state','Which ordered pair is used by the displayed pendulum phase portrait?', ['(Actual angle in radians, actual angular velocity in rad/s)','(Time in seconds, actuator torque in N·m)','(Position error in radians, error acceleration in rad/s²)','(Desired angle in degrees, actual angle in degrees)'],0,'The phase plot labels its axes θ(rad) and θ_dot(rad/s), so it traces actual angle-speed state.',['This matches the visible axes.','This describes a torque time-history, not the phase portrait.','Neither plotted axis is the stated error acceleration.','The axes are actual state in radians and radians per second.'],typ='diagram')
add(720,'still-frame-evidence','Distinguish an animation frame from executable animation code','What can the shown animation still frame establish about the source material?', ['The displayed geometry, labels and one time-state snapshot, but not the missing animation implementation','That the screenshot includes every animation callback and rendering command','That the animation was independently executed in this study application','That the robot completed an equivalent hardware motion'],0,'A static frame supplies visual evidence of the shown scene, not the absent code or a separate execution/hardware verification.',['This is the appropriate scope of the evidence.','The callback code is not present in the screenshot.','A source image is not an application execution record.','No hardware experiment is established by this figure.'],typ='diagram')
add(721,'mimo-reference-consistency','Keep vector reference derivatives consistent','For one component of a joint reference X_d(t)=t² in stated position units, which corresponding desired velocity and acceleration must the servo use?', ['2t and2','t and1','t² andt','2 and2t'],0,'The velocity and acceleration references must be first and second time derivatives of the desired position, not independent arbitrary signals.',['These are the consistent derivatives.','The first derivative is missing a factor two.','These are not successive derivatives.','This swaps the time dependence between velocity and acceleration.'],typ='numerical',steps=['Differentiate t² to obtain2t.','Differentiate2t to obtain2.'],assumptions=['The coefficient of t² has the required position-per-time-squared units.'])
add(721,'mimo-coupling','Interpret coupling in an n-joint model','What does a nonzero off-diagonal entry of the joint-space inertia matrix generally signify?', ['Acceleration of one joint can contribute to generalized torque at another joint','Each actuator necessarily controls only its own independent scalar inertia','The inertia matrix is invalid because every physical inertia matrix must be diagonal','The system has more physical joints than generalized coordinates by definition'],0,'Off-diagonal entries represent inertial coupling between the chosen generalized coordinates.',['This is the meaning of cross-coordinate inertia terms.','This ignores the coupling.','A symmetric positive-definite matrix can have nonzero off-diagonal entries.','Matrix coupling does not determine such a coordinate-count mismatch.'])
add(722,'mimo-dimensions','Check the vector partition dimensions','For n fully actuated generalized coordinates in F=αF′+β, what dimensions are consistent?', ['α is n×n; F,F′,β are n×1','α is n×1; F,F′,β are all n×n','α is a scalar for every coupled plant; β is1×n and F is n×1','α is n×n; F′ is1×n without transposition'],0,'The matrix-vector product αF′ must be an n-component column vector so it can be added to β and equal F.',['This makes multiplication and addition well-defined.','These shapes do not represent the stated matrix-vector partition.','A scalar cannot generally represent the coupled mass matrix, and row/column addition is inconsistent.','An n×n matrix does not multiply a1×n row in the stated order for general n.'],typ='definition')
add(722,'mimo-exact-cancellation','Derive the normalized coupled plant','Given M(X)Ẍ+h(X,Ẋ)=F, choose F=M(X)F′+h(X,Ẋ); what follows if M is invertible and the model is exact?', ['Ẍ=F′ even when M has off-diagonal coupling','Ẍ=M F′ because the inertia remains twice in the equation','Ẍ=F′ only when every off-diagonal inertia entry is zero','Ẍ=F′+h because adding h cannot cancel an LHS term'],0,'Cancel h to obtain M Ẍ=M F′ and multiply by M⁻¹; off-diagonal coupling does not prevent exact full-matrix cancellation.',['This is the normalized model under the stated assumptions.','The remaining M occurs on both sides and cancels.','Invertibility, not diagonality, is the relevant condition here.','The same h appears on both sides.'],typ='derivation',assumptions=matched,steps=['Substitute the partitioned input.','Cancel the common vector h.','Multiply by M⁻¹.'],formulas=[formula('F=M(X)F′+h; M(X)Ẍ+h=F ⇒ Ẍ=F′',{'X':'generalized-position vector','M':'inertia matrix','F':'generalized force/torque input','F′':'normalized acceleration vector','h':'combined modeled non-inertial generalized-force vector'},{'X':'rad for an all-revolute example','M':'kg·m² for that example','F,h':'N·m for that example','F′':'rad/s²'},matched)])
add(722,'mimo-torque-numerical','Compute a coupled two-joint input','For an all-revolute example with M=[[2,1],[1,3]]kg·m², F′=[1,−2]rad/s² and β=[0.5,1]N·m, what is F=M F′+β?', ['[0.5,−4]N·m','[2.5,−5]N·m','[−0.5,−6]N·m','[3.5,8]N·m'],0,'The matrix product is[2−2,1−6]=[0,−5]; addingβ gives[0.5,−4].',['This includes the coupling and offset.','This omits the off-diagonal contributions.','This subtracts β instead of adding it.','This changes the negative acceleration to positive.'],typ='numerical',difficulty='medium',steps=['Compute row1:2×1+1×(−2)=0.','Compute row2:1×1+3×(−2)=−5.','Add[0.5,1].'])
add([722,723],'diagonal-servo-gains','Distinguish diagonal servo gains from a diagonal plant','After exact full-matrix cancellation, the lecture uses diagonal K_p and K_v; what does this imply?', ['Each normalized error component can have its own scalar gains even though the original inertia matrix was coupled','The original physical mass matrix must have been diagonal','Every joint must use identical gain values because both matrices are diagonal','The physical inertia of each link has literally become one kilogram'],0,'Diagonal normalized gains separate the ideal error equations; that is a controller/model transformation, not a claim about uncoupled physical inertia or identical gains.',['This is the purpose of the displayed diagonal gains.','Full-matrix cancellation can remove modeled coupling before the servo.','Diagonal entries can differ from joint to joint.','Normalized dynamics do not physically change mass.'])
add(723,'vector-error-gains','Select critical gains for two normalized joint errors','For diagonal K_p=diag(9,25)s⁻², which diagonal K_v makes both independent normalized error equations critically damped?', ['diag(6,10)s⁻¹','diag(3,5)s⁻¹','diag(18,50)s⁻¹','diag(10,6)s⁻¹'],0,'Apply k_v,i=2√k_p,i componentwise:2√9=6 and2√25=10.',['This matches each joint’s own stiffness gain.','This omits the factor two.','This doubles the stiffness values without taking square roots.','This swaps the required gains between joints.'],typ='numerical',steps=['Use the critical-damping rule for each diagonal scalar equation.','Calculate the two square roots and multiply by two.'])
add(723,'vector-servo-signs','Write the vector tracking-error equation','With E=X_d−X and F′=Ẍ_d+K_v Ė+K_p E after exact cancellation, which vector error equation follows?', ['Ë+K_v Ė+K_p E=0','Ë−K_v Ė−K_p E=0','Ë+K_v E+K_p Ė=0 with the same gain definitions','Ë=Ẍ_d+K_v Ė+K_p E'],0,'Subtract the normalized actual acceleration from desired acceleration; the feedforward terms cancel, leaving negative error feedback on the right.',['This follows the stated vector error convention.','This reverses the feedback signs.','This swaps position and velocity feedback terms.','This confuses normalized actual acceleration with error acceleration.'],typ='derivation',steps=['Differentiate E=X_d−X twice.','Substitute Ẍ=F′ and the servo expression.','Cancel Ẍ_d and rearrange.'])
